import { ClickHouseClient, createClickHouseQuery } from "@514labs/moose-lib";

export interface TopProductsResponse {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
  total_events: number;
  last_activity: string;
}

// API endpoint for top products analytics
export default async function GET(client: ClickHouseClient): Promise<TopProductsResponse[]> {
  const query = `
    SELECT
        product_id,
        countIf(event_type = 'view') as view_count,
        countIf(event_type = 'cart') as cart_count,
        countIf(event_type = 'purchase') as purchase_count,
        sumIf(JSONExtractFloat(properties, 'price'), event_type = 'purchase') as total_revenue,
        count(*) as total_events,
        max(event_ts) as last_activity
    FROM currentDatabase().ProductEvent
    GROUP BY product_id
    ORDER BY total_revenue DESC, purchase_count DESC, view_count DESC
    LIMIT 50
  `;

  const result = await createClickHouseQuery<TopProductsResponse>(client, query);
  return result;
}

import { ClickHouseClient, createClickHouseQuery } from "@514labs/moose-lib";

export interface ConversionFunnelResponse {
  funnel_step: string;
  total_events: number;
  unique_users: number;
  conversion_rate_from_views: number;
}

// API endpoint for conversion funnel analytics
export default async function GET(client: ClickHouseClient): Promise<ConversionFunnelResponse[]> {
  const query = `
    SELECT
        event_type as funnel_step,
        count(*) as total_events,
        uniq(user_id) as unique_users,
        count(*) / (SELECT count(*) FROM currentDatabase().ProductEvent WHERE event_type = 'view') * 100 as conversion_rate_from_views
    FROM currentDatabase().ProductEvent
    WHERE event_type IN ('view', 'cart', 'purchase')
    GROUP BY event_type
    ORDER BY
        CASE
            WHEN event_type = 'view' THEN 1
            WHEN event_type = 'cart' THEN 2
            WHEN event_type = 'purchase' THEN 3
            ELSE 4
        END
  `;

  const result = await createClickHouseQuery<ConversionFunnelResponse>(client, query);
  return result;
}

